const cmds = [
  ["contract", "cat benchmark_contract.md; printf '\\n--- README ---\\n'; cat README.md"],
  ["launch", "cat run.sh; printf '\\n--- run_protocol.py ---\\n'; sed -n '1,260p' run_protocol.py; printf '\\n--- pyproject ---\\n'; cat pyproject.toml; printf '\\n--- setup ---\\n'; cat setup.py"],
  ["case", "for f in case/*.py case/*.yaml; do echo \"--- $f ---\"; sed -n '1,300p' \"$f\"; done"],
  ["artifacts", "printf '%s\\n' '--- metrics ---'; cat outputs/metrics.jsonl; printf '%s\\n' '--- train.log ---'; cat outputs/train.log"],
  ["rollouts", "for f in outputs/rollouts/*.jsonl outputs/frozen_eval/*.jsonl; do echo \"--- $f ---\"; cat \"$f\"; done"]
];
const rs = await Promise.allSettled(cmds.map(([name, cmd]) => tools.exec_command({cmd, workdir:"/workspace", yield_time_ms:10000, max_output_tokens:30000})));
for (let i=0;i<rs.length;i++) {
  const x=rs[i];
  text(`### ${cmds[i][0]} ###\n`);
  if (x.status==="fulfilled") text(x.value.output);
  else text(String(x.reason));
}

